    56→            animationDuration: `${speed}s`,
    57→          }}
    58→        >
    59→          {logos.map((logo, index) => (
    60→            <span key={`second-${logo.alt}-${index}`} className="flex items-center shrink-0">
    61→              <span className="mx-8 md:mx-16 flex items-center justify-center">
    62→                <Image
    63→                  src={logo.src}
    64→                  alt={logo.alt}
    65→                  width={logo.size === "large" ? 350 : 200}
