    68→                    logo.size === "large" ? "h-28 md:h-44" : "h-16 md:h-24"
    69→                  }`}
    70→                  style={{ maxWidth: logo.size === "large" ? "350px" : "220px" }}
    71→                />
    72→              </span>
    73→              <span className="w-2 h-2 md:w-3 md:h-3 bg-neo-accent block rounded-full shrink-0" />
    74→            </span>
